static int32_t clamp(int32_t v, int32_t lo, int32_t hi)
{
    if (v < lo) {
        return lo;
    }
    if (v > hi) {
        return hi;
    }
    return v;
}

/** @brief Initialize a PID controller with given gains and output limits.
 *
 *  @param p Pointer to the PID controller structure to initialize.
 *  @param kp_q8 Proportional gain in Q8.8 fixed-point format (8.8).
 *  @param ki_q8 Integral gain in Q8.8 fixed-point format (8.8).
 *  @param kd_q8 Derivative gain in Q8.8 fixed-point format (8.8).
 *  @param out_min Minimum allowed output value.
 *  @param out_max Maximum allowed output value.
 */
void pid_init(pid_t_ *p, int32_t kp_q8, int32_t ki_q8, int32_t kd_q8, int32_t out_min, int32_t out_max)
{
    p->kp_q8 = kp_q8;
    p->ki_q8 = ki_q8;
    p->kd_q8 = kd_q8;
    p->integral = 0;
    p->integral_limit = 100000;
    p->prev_error = 0;
    p->out_min = out_min;
    p->out_max = out_max;
}

/** @brief Execute one step of the PID control loop.
 *
 *  @param p Pointer to the initialized PID controller structure.
 *  @param setpoint Desired target value (units same as measurement).
 *  @param measurement Current measured value (units same as setpoint).
 *  @return Control output value clamped to [out_min, out_max].
 */
int32_t pid_step(pid_t_ *p, int32_t setpoint, int32_t measurement)
{
    int32_t error = setpoint - measurement;
    int32_t derivative = error - p->prev_error;
    p->integral = clamp(p->integral + error, -p->integral_limit, p->integral_limit);
    p->prev_error = error;
    int32_t out = (p->kp_q8 * error + p->ki_q8 * p->integral + p->kd_q8 * derivative) / 256;
    return clamp(out, p->out_min, p->out_max);
}

#include "task.h"

/** @brief Initialize a ring buffer to empty state.
 *
 *  @param rb Pointer to ring_buffer_t to initialize.
 */
void rb_init(ring_buffer_t *rb)
{
    rb->head = 0u;
    rb->tail = 0u;
    rb->count = 0u;
}

/** @brief Push a byte into the ring buffer.
 *
 *  @param rb Pointer to ring_buffer_t to push into.
 *  @param byte Byte value to store.
 *  @return true if byte was stored, false if buffer was full.
 */
bool rb_push(ring_buffer_t *rb, uint8_t byte)
{
    if (rb->count >= RB_CAPACITY) {
        return false;
    }
    rb->data[rb->head] = byte;
    rb->head = (rb->head + 1u) % RB_CAPACITY;
    rb->count++;
    return true;
}

/** @brief Pop a byte from the ring buffer.
 *
 *  @param rb Pointer to ring_buffer_t to pop from.
 *  @param[out] out Pointer to store popped byte (untouched on failure).
 *  @return true if byte was retrieved, false if buffer was empty.
 */
bool rb_pop(ring_buffer_t *rb, uint8_t *out)
{
    if (rb->count == 0u) {
        return false;
    }
    *out = rb->data[rb->tail];
    rb->tail = (rb->tail + 1u) % RB_CAPACITY;
    rb->count--;
    return true;
}

/** @brief Get current number of bytes in the ring buffer.
 *
 *  @param rb Pointer to ring_buffer_t to query.
 *  @return Number of bytes currently stored (0 to RB_CAPACITY).
 */
size_t rb_count(const ring_buffer_t *rb) { return rb->count; }

/** @brief Push multiple bytes into the ring buffer.
 *
 *  @param rb Pointer to ring_buffer_t to push into.
 *  @param src Pointer to array of bytes to store.
 *  @param n Number of bytes to attempt to store.
 *  @return Number of bytes actually stored (0 to n).
 */
size_t rb_push_many(ring_buffer_t *rb, const uint8_t *src, size_t n)
{
    size_t stored = 0u;
    while (stored < n && rb_push(rb, src[stored])) {
        stored++;
    }
    return stored;
}

