/** @brief Performs saturating addition of two 16-bit signed integers.
 *
 *  @param a First operand in range [INT16_MIN, INT16_MAX].
 *  @param b Second operand in range [INT16_MIN, INT16_MAX].
 *  @return Result of a + b clamped to [INT16_MIN, INT16_MAX].
 */
int16_t sat_add16(int16_t a, int16_t b) { return clamp16((int32_t)a + (int32_t)b); }

/** @brief Performs saturating subtraction of two 16-bit signed integers.
 *
 *  @param a First operand in range [INT16_MIN, INT16_MAX].
 *  @param b Second operand in range [INT16_MIN, INT16_MAX].
 *  @return Result of a - b clamped to [INT16_MIN, INT16_MAX].
 */
int16_t sat_sub16(int16_t a, int16_t b) { return clamp16((int32_t)a - (int32_t)b); }

/** @brief Performs saturating absolute value of a 16-bit signed integer.
 *
 *  @param a Input value in range [INT16_MIN, INT16_MAX].
 *  @return Absolute value of a clamped to [INT16_MIN, INT16_MAX].
 *  @note sat_abs16(INT16_MIN) returns INT16_MAX to avoid overflow.
 */
int16_t sat_abs16(int16_t a) { return clamp16(a < 0 ? -(int32_t)a : (int32_t)a); }

#include "task.h"

int ccsds_parse_primary(const uint8_t *buf, size_t len, ccsds_primary_header_t *hdr) {
    if (buf == NULL || hdr == NULL || len < 6) {
        return -1;
    }

    uint32_t header = ((uint32_t)buf[0] << 24) | ((uint32_t)buf[1] << 16) |
                      ((uint32_t)buf[2] << 8)  | ((uint32_t)buf[3] << 0);

    hdr->version = (header >> 30) & 0x7;
    hdr->type = (header >> 29) & 0x1;
    hdr->sec_hdr = (header >> 28) & 0x1;
    hdr->apid = (header >> 17) & 0x7FF;
    hdr->seq_flags = (header >> 15) & 0x3;
    hdr->seq_count = (header >> 1) & 0x3FFF;
    hdr->data_length = ((uint16_t)buf[4] << 8) | buf[5];

    if (hdr->version != 0) {
        return -2;
    }

    return 0;
}

size_t ccsds_packet_length(const ccsds_primary_header_t *hdr) {
    return 6 + hdr->data_length + 1;
}

int ccsds_build_primary(const ccsds_primary_header_t *hdr, uint8_t out[6]) {
    if (hdr->version > 7 || hdr->type > 1 || hdr->sec_hdr > 1 ||
        hdr->apid > 2047 || hdr->seq_flags > 3 || hdr->seq_count > 16383) {
        return -1;
    }

    uint32_t header = ((hdr->version & 0x7) << 30) | ((hdr->type & 0x1) << 29) |
                      ((hdr->sec_hdr & 0x1) << 28) | ((hdr->apid & 0x7FF) << 17) |
                      ((hdr->seq_flags & 0x3) << 15) | ((hdr->seq_count & 0x3FFF) << 1);

    out[0] = (header >> 24) & 0xFF;
    out[1] = (header >> 16) & 0xFF;
    out[2] = (header >> 8) & 0xFF;
    out[3] = header & 0xFF;
    out[4] = (hdr->data_length >> 8) & 0xFF;
    out[5] = hdr->data_length & 0xFF;

    return 0;
}

