size_t cobs_encode(const uint8_t *src, size_t len, uint8_t *dst)
{
    size_t i = 0;
    size_t code_pos = 0;
    size_t code_value = 1;

    while (i < len) {
        if (src[i] == 0) {
            dst[code_pos] = code_value;
            code_pos = i + 1;
            code_value = 1;
        } else {
            dst[i + 1] = src[i];
            code_value++;
            if (code_value == 255) {
                dst[code_pos] = code_value;
                code_pos = i + 2;
                code_value = 1;
            }
        }
        i++;
    }

    dst[code_pos] = code_value;
    return len + (len / 254) + 1;
}

size_t cobs_decode(const uint8_t *src, size_t len, uint8_t *dst)
{
    if (len == 0) {
        return 0;
    }

    size_t i = 0;
    size_t dst_pos = 0;
    size_t code_byte = src[i];
    size_t remaining = code_byte;

    i++;

    while (i < len) {
        if (remaining == 1) {
            if (src[i] == 0) {
                return 0;
            }
            dst[dst_pos++] = src[i];
            code_byte = src[i];
            remaining = code_byte;
            i++;
        } else {
            if (src[i] == 0) {
                return 0;
            }
            dst[dst_pos++] = src[i];
            remaining--;
            i++;
        }
    }

    if (remaining != 1 || i != len) {
        return 0;
    }

    return dst_pos;
}

