size_t conv_encode(const uint8_t *in, size_t nbits, uint8_t *out)
{
    uint8_t state = 0; /* p2 p1 u */
    size_t out_bits = 0;
    size_t out_byte = 0;
    uint8_t out_accum = 0;

    for (size_t i = 0; i < nbits; ++i)
    {
        /* Extract current input bit (MSB first) */
        uint8_t u = (in[i / 8] >> (7 - (i % 8))) & 1;

        /* Compute output bits */
        uint8_t out0 = u ^ ((state >> 1) & 1) ^ (state & 1);
        uint8_t out1 = u ^ ((state >> 2) & 1);

        /* Pack output bits into output array (MSB first) */
        out_accum = (out_accum << 1) | out0;
        ++out_bits;
        if (out_bits % 8 == 0)
        {
            out[out_byte++] = out_accum;
            out_accum = 0;
        }

        out_accum = (out_accum << 1) | out1;
        ++out_bits;
        if (out_bits % 8 == 0)
        {
            out[out_byte++] = out_accum;
            out_accum = 0;
        }

        /* Update state (shift in new bit, drop oldest) */
        state = (state << 1) | u;
    }

    /* Handle remaining bits in the last byte */
    if (out_bits % 8 != 0)
    {
        out_accum <<= (8 - (out_bits % 8));
        out[out_byte] = out_accum;
    }

    return out_bits;
}

