void debounce_init(debounce_t *d, bool initial)
{
    if (d != NULL)
    {
        d->state = initial;
        d->count = 0u;
    }
}

bool debounce_update(debounce_t *d, bool raw)
{
    if (d == NULL)
    {
        return false;
    }

    if (raw == d->state)
    {
        d->count = 0u;
    }
    else
    {
        d->count++;
        if (d->count >= DEBOUNCE_SAMPLES)
        {
            d->state = raw;
            d->count = 0u;
        }
    }

    return d->state;
}

