uint8_t hamming74_encode(uint8_t nibble) {
    uint8_t codeword = nibble & 0x0F;
    uint8_t p1 = __builtin_parity(codeword & 0x55) ^ ((codeword >> 2) & 1);
    uint8_t p2 = __builtin_parity(codeword & 0x66) ^ ((codeword >> 1) & 1);
    uint8_t p3 = __builtin_parity(codeword & 0x77) ^ (codeword & 1);
    return (p1 << 6) | (p2 << 5) | (p3 << 3) | codeword;
}

int hamming74_decode(uint8_t codeword, uint8_t *nibble) {
    uint8_t p1 = (codeword >> 6) & 1;
    uint8_t p2 = (codeword >> 5) & 1;
    uint8_t p3 = (codeword >> 3) & 1;
    uint8_t d1 = (codeword >> 2) & 1;
    uint8_t d2 = (codeword >> 1) & 1;
    uint8_t d3 = codeword & 1;
    uint8_t d4 = (codeword >> 4) & 1;

    uint8_t received_p1 = __builtin_parity(d1 | d3 | d4);
    uint8_t received_p2 = __builtin_parity(d1 | d2 | d4);
    uint8_t received_p3 = __builtin_parity(d2 | d3 | d4);

    uint8_t error_pos = 0;
    if (received_p1 != p1) error_pos |= 1;
    if (received_p2 != p2) error_pos |= 2;
    if (received_p3 != p3) error_pos |= 4;

    if (error_pos == 0) {
        *nibble = (d1 << 3) | (d2 << 2) | (d3 << 1) | d4;
        return 0;
    } else if (error_pos <= 7) {
        codeword ^= (1 << (7 - error_pos));
        *nibble = ((codeword >> 2) & 1) << 3 |
                  ((codeword >> 1) & 1) << 2 |
                  (codeword & 1) << 1 |
                  ((codeword >> 4) & 1);
        return 1;
    } else {
        *nibble = 0;
        return 0;
    }
}

