#define OPCODE_SET_MODE      0x01
#define OPCODE_SET_GAIN      0x02
#define OPCODE_SET_CHANNEL   0x03
#define OPCODE_RESET         0x04
#define OPCODE_PING          0x05

#define MODE_ACTIVE          1
#define GAIN_MIN             0
#define GAIN_MAX             63
#define CHANNEL_MIN          1
#define CHANNEL_MAX          15
#define RESET_MAGIC          0xA5

#define SUCCESS              0
#define ERROR_UNKNOWN_OPCODE -1
#define ERROR_ARG_OUT_OF_RANGE -2
#define ERROR_COMMAND_NOT_ALLOWED -3

static void reset_state(payload_state_t *s)
{
    s->mode = 0;
    s->gain = 10;
    s->channel = 1;
}

void payload_init(payload_state_t *s)
{
    reset_state(s);
    s->cmd_count = 0;
    s->err_count = 0;
}

static int handle_set_mode(payload_state_t *s, uint8_t arg)
{
    if (arg > 3) {
        s->err_count++;
        return ERROR_ARG_OUT_OF_RANGE;
    }
    s->mode = arg;
    s->cmd_count++;
    return SUCCESS;
}

static int handle_set_gain(payload_state_t *s, uint8_t arg)
{
    if (s->mode == 0) {
        s->err_count++;
        return ERROR_COMMAND_NOT_ALLOWED;
    }
    if (arg > GAIN_MAX) {
        s->err_count++;
        return ERROR_ARG_OUT_OF_RANGE;
    }
    s->gain = arg;
    s->cmd_count++;
    return SUCCESS;
}

static int handle_set_channel(payload_state_t *s, uint8_t arg)
{
    if (s->mode == 0) {
        s->err_count++;
        return ERROR_COMMAND_NOT_ALLOWED;
    }
    if (arg < CHANNEL_MIN || arg > CHANNEL_MAX) {
        s->err_count++;
        return ERROR_ARG_OUT_OF_RANGE;
    }
    s->channel = arg;
    s->cmd_count++;
    return SUCCESS;
}

static int handle_reset(payload_state_t *s, uint8_t arg)
{
    if (arg != RESET_MAGIC) {
        s->err_count++;
        return ERROR_ARG_OUT_OF_RANGE;
    }
    reset_state(s);
    s->cmd_count++;
    return SUCCESS;
}

static int handle_ping(payload_state_t *s)
{
    (void)arg; // Unused parameter
    s->cmd_count++;
    return SUCCESS;
}

int payload_dispatch(payload_state_t *s, uint8_t opcode, uint8_t arg)
{
    switch (opcode) {
        case OPCODE_SET_MODE:      return handle_set_mode(s, arg);
        case OPCODE_SET_GAIN:      return handle_set_gain(s, arg);
        case OPCODE_SET_CHANNEL:   return handle_set_channel(s, arg);
        case OPCODE_RESET:         return handle_reset(s, arg);
        case OPCODE_PING:          return handle_ping(s);
        default:                   s->err_count++; return ERROR_UNKNOWN_OPCODE;
    }
}

