static const uint32_t FREQ_MIN_KHZ = 400000;
static const uint32_t FREQ_MAX_KHZ = 470000;
static const uint32_t FREQ_STEP_KHZ = 25;
static const uint16_t BANDWIDTHS_KHZ[] = {125, 250, 500};
static const size_t BANDWIDTHS_COUNT = sizeof(BANDWIDTHS_KHZ) / sizeof(BANDWIDTHS_KHZ[0]);
static const uint8_t SF_MIN = 7;
static const uint8_t SF_MAX = 12;
