static int validate_frequency(uint32_t freq_khz)
{
    if (freq_khz < FREQ_MIN_KHZ || freq_khz > FREQ_MAX_KHZ) return 1;
    if (freq_khz % FREQ_STEP_KHZ != 0) return 2;
    return 0;
}

static int validate_bandwidth(uint16_t bw_khz)
{
    for (size_t i = 0; i < BANDWIDTHS_COUNT; i++) {
        if (bw_khz == BANDWIDTHS_KHZ[i]) return 0;
    }
    return 3;
}

static int validate_spreading_factor(uint8_t sf)
{
    if (sf < SF_MIN || sf > SF_MAX) return 4;
    return 0;
}

static int validate_tx_power(int8_t tx_power_dbm)
{
    if (tx_power_dbm < TX_POWER_MIN_DBM || tx_power_dbm > TX_POWER_MAX_DBM) return 5;
    return 0;
}

static int validate_bandwidth_sf_constraint(uint16_t bw_khz, uint8_t sf)
{
    if (bw_khz == 500 && sf > 10) return 6;
    return 0;
}

static int validate_duty_cycle(int8_t tx_power_dbm, uint8_t duty_cycle_pct)
{
    if (tx_power_dbm > 14 && duty_cycle_pct > 10) return 7;
    if (duty_cycle_pct < DUTY_CYCLE_MIN_PCT || duty_cycle_pct > DUTY_CYCLE_MAX_PCT) return 8;
    return 0;
}

int radio_cfg_validate(const radio_cfg_t *c)
{
    int err = validate_frequency(c->frequency_khz);
    if (err) return err;

    err = validate_bandwidth(c->bandwidth_khz);
    if (err) return err;

    err = validate_spreading_factor(c->spreading_factor);
    if (err) return err;

    err = validate_tx_power(c->tx_power_dbm);
    if (err) return err;

    err = validate_bandwidth_sf_constraint(c->bandwidth_khz, c->spreading_factor);
    if (err) return err;

    err = validate_duty_cycle(c->tx_power_dbm, c->duty_cycle_pct);
    if (err) return err;

    return 0;
}

#include "task.h"

static const uint8_t SYNC_BYTE_1 = 0xEB;
static const uint8_t SYNC_BYTE_2 = 0x90;
static const uint8_t MIN_TYPE = 0x10;
static const uint8_t MAX_TYPE = 0x1F;
static const size_t MIN_FRAME_LEN = 5;
static const size_t MAX_PAYLOAD_LEN = 32;

static int validate_sync(const uint8_t *buf)
{
    return (buf[0] == SYNC_BYTE_1 && buf[1] == SYNC_BYTE_2) ? 0 : -2;
}

static int validate_length(const uint8_t *buf, size_t len)
{
    uint8_t payload_len = buf[2];
    if (payload_len == 0 || payload_len > MAX_PAYLOAD_LEN) {
        return -3;
    }
    if ((size_t)payload_len + MIN_FRAME_LEN != len) {
        return -3;
    }
    return 0;
}

static int validate_type(const uint8_t *buf)
{
    uint8_t frame_type = buf[3];
    return (frame_type >= MIN_TYPE && frame_type <= MAX_TYPE) ? 0 : -4;
}

static uint8_t compute_checksum(const uint8_t *buf, size_t payload_len)
{
    uint8_t checksum = buf[2] ^ buf[3];
    for (size_t i = 0; i < payload_len; i++) {
        checksum ^= buf[4 + i];
    }
    return checksum;
}

int frame_parse(const uint8_t *buf, size_t len, uint8_t *type, uint8_t *out)
{
    if (buf == NULL || type == NULL || out == NULL) {
        return -1;
    }
    if (len < MIN_FRAME_LEN) {
        return -1;
    }

    int rc = validate_sync(buf);
    if (rc != 0) return rc;

    rc = validate_length(buf, len);
    if (rc != 0) return rc;

    rc = validate_type(buf);
    if (rc != 0) return rc;

    uint8_t payload_len = buf[2];
    uint8_t computed_checksum = compute_checksum(buf, payload_len);
    if (computed_checksum != buf[4 + payload_len]) {
        return -5;
    }

    *type = buf[3];
    for (size_t i = 0; i < payload_len; i++) {
        out[i] = buf[4 + i];
    }
    return payload_len;
}

#include "task.h"

typedef enum {
    MODE_OFF = 0,
    MODE_STANDBY,
    MODE_OPERATE,
    MODE_FAULT
} mode_t;

typedef enum {
    EVENT_POWER_ON = 0,
    EVENT_POWER_OFF,
    EVENT_START,
    EVENT_STOP,
    EVENT_ERROR,
    EVENT_CLEAR
} event_t;

static const uint8_t transition_table[4][6] = {
    [MODE_OFF][EVENT_POWER_ON] = MODE_STANDBY,
    [MODE_STANDBY][EVENT_START] = MODE_OPERATE,
    [MODE_STANDBY][EVENT_ERROR] = MODE_FAULT,
    [MODE_OPERATE][EVENT_STOP] = MODE_STANDBY,
    [MODE_OPERATE][EVENT_ERROR] = MODE_FAULT,
    [MODE_FAULT][EVENT_CLEAR] = MODE_STANDBY,
    [MODE_FAULT][EVENT_ERROR] = MODE_FAULT
};

static int is_valid_event(uint8_t event) {
    return event <= EVENT_CLEAR;
}

void mode_init(mode_mgr_t *m) {
    m->mode = MODE_OFF;
    m->transitions = 0;
}

int mode_handle(mode_mgr_t *m, uint8_t event) {
    if (!is_valid_event(event)) {
        return 0;
    }

    uint8_t new_mode = transition_table[m->mode][event];
    if (new_mode != 0) {
        m->mode = new_mode;
        m->transitions++;
        return 1;
    }

    return 0;
}

#include "task.h"

static const int32_t TEMP_MIN = -1000;
static const int32_t TEMP_MAX = 1500;
static const int32_t VOLT_MIN = 0;
static const int32_t VOLT_MAX = 40000;
static const uint8_t GAIN_MAX = 63;
static const uint8_t MODE_MASK = 3;
static const uint8_t CHANNEL_MASK = 15;
static const uint8_t HEATER_BIT = 1 << 5;
static const uint8_t FAULT_BIT = 1 << 4;

static int32_t clamp_temp(int32_t temp)
{
    if (temp < TEMP_MIN) return TEMP_MIN;
    if (temp > TEMP_MAX) return TEMP_MAX;
    return temp;
}

static int32_t clamp_volt(int32_t volt)
{
    if (volt < VOLT_MIN) return VOLT_MIN;
    if (volt > VOLT_MAX) return VOLT_MAX;
    return volt;
}

static uint8_t clamp_gain(uint8_t gain)
{
    return (gain > GAIN_MAX) ? GAIN_MAX : gain;
}

static uint8_t pack_byte0(const hk_t *hk)
{
    uint8_t b0 = (uint8_t)((hk->mode & MODE_MASK) << 6);
    if (hk->heater_on) b0 |= HEATER_BIT;
    if (hk->fault) b0 |= FAULT_BIT;
    b0 |= (uint8_t)(hk->channel & CHANNEL_MASK);
    return b0;
}

static void pack_temp(int32_t temp, uint8_t out[2])
{
    temp = clamp_temp(temp);
    out[0] = (uint8_t)(((uint16_t)(int16_t)temp >> 8) & 0xFF);
    out[1] = (uint8_t)((uint16_t)(int16_t)temp & 0xFF);
}

static void pack_volt(int32_t volt, uint8_t out[2])
{
    volt = clamp_volt(volt);
    out[0] = (uint8_t)(((uint32_t)volt >> 8) & 0xFF);
    out[1] = (uint8_t)((uint32_t)volt & 0xFF);
}

static void pack_counter(uint16_t counter, uint8_t out[2])
{
    out[0] = (uint8_t)((counter >> 8) & 0xFF);
    out[1] = (uint8_t)(counter & 0xFF);
}

void hk_pack(const hk_t *hk, uint8_t out[8])
{
    out[0] = pack_byte0(hk);
    pack_temp(hk->temp_decic, out + 1);
    pack_volt(hk->bus_mv, out + 3);
    out[5] = clamp_gain(hk->gain);
    pack_counter(hk->counter, out + 6);
}

