static void test_fletcher16_basic(void)
{
    CHECK_EQ_U(fletcher16(NULL, 0), 0);
    CHECK_EQ_U(fletcher16((uint8_t[]){0}, 1), 0);
    CHECK_EQ_U(fletcher16((uint8_t[]){1}, 1), 1);
    CHECK_EQ_U(fletcher16((uint8_t[]){255}, 1), 255);
    CHECK_EQ_U(fletcher16((uint8_t[]){1, 2}, 2), 0x0003);
    CHECK_EQ_U(fletcher16((uint8_t[]){1, 2, 3}, 3), 0x0006);
    CHECK_EQ_U(fletcher16((uint8_t[]){255, 255}, 2), 0xFFFF);
}

static void test_fletcher16_large(void)
{
    uint8_t data[256] = {0};
    for (size_t i = 0; i < 256; ++i) {
        data[i] = (uint8_t)i;
    }
    CHECK_EQ_U(fletcher16(data, 256), 0x0000);
}

static void test_fletcher16_frame_ok(void)
{
    uint8_t frame[3] = {1, 2, 0x03, 0x00}; /* 2-byte frame with correct check */
    frame[2] = (uint8_t)(0x03 & 0xFF);
    frame[3] = (uint8_t)(0x00 & 0xFF);
    CHECK(fletcher16_frame_ok(frame, 4) == 1);
    frame[2] ^= 0xFF; /* corrupt check */
    CHECK(fletcher16_frame_ok(frame, 4) == 0);
    CHECK(fletcher16_frame_ok(frame, 1) == 0);
    CHECK(fletcher16_frame_ok(frame, 0) == 0);
}

int main(void)
{
    test_fletcher16_basic();
    test_fletcher16_large();
    test_fletcher16_frame_ok();
    return OGE_REPORT();
}

