#include "task.h"
#include "oge_test.h"

static void test_init(void)
{
    ring_buffer_t rb;
    rb_init(&rb);
    CHECK_EQ_U(rb.head, 0u);
    CHECK_EQ_U(rb.tail, 0u);
    CHECK_EQ_U(rb.count, 0u);
}

static void test_push_pop(void)
{
    ring_buffer_t rb;
    rb_init(&rb);

    uint8_t out;
    CHECK(!rb_pop(&rb, &out));

    CHECK(rb_push(&rb, 0x12));
    CHECK_EQ_U(rb_count(&rb), 1u);
    CHECK(rb_pop(&rb, &out));
    CHECK_EQ_U(out, 0x12u);
    CHECK_EQ_U(rb_count(&rb), 0u);
}

static void test_full_buffer(void)
{
    ring_buffer_t rb;
    rb_init(&rb);

    uint8_t data[RB_CAPACITY] = {0x11, 0x22, 0x33, 0x44, 0x55};
    for (size_t i = 0; i < RB_CAPACITY; i++) {
        CHECK(rb_push(&rb, data[i]));
    }
    CHECK_EQ_U(rb_count(&rb), RB_CAPACITY);
    CHECK(!rb_push(&rb, 0x66));

    uint8_t out;
    for (size_t i = 0; i < RB_CAPACITY; i++) {
        CHECK(rb_pop(&rb, &out));
        CHECK_EQ_U(out, data[i]);
    }
    CHECK_EQ_U(rb_count(&rb), 0u);
    CHECK(!rb_pop(&rb, &out));
}

static void test_wrap_around(void)
{
    ring_buffer_t rb;
    rb_init(&rb);

    uint8_t data[RB_CAPACITY + 2] = {0x11, 0x22, 0x33, 0x44, 0x55, 0x66, 0x77};
    size_t stored = rb_push_many(&rb, data, sizeof(data));
    CHECK_EQ_U(stored, RB_CAPACITY);

    uint8_t out;
    CHECK(rb_pop(&rb, &out));
    CHECK_EQ_U(out, 0x11u);
    CHECK(rb_push(&rb, 0x66));
    CHECK(rb_pop(&rb, &out));
    CHECK_EQ_U(out, 0x22u);
    CHECK(rb_push(&rb, 0x77));
    CHECK_EQ_U(rb_count(&rb), RB_CAPACITY);

    for (size_t i = 2; i < RB_CAPACITY; i++) {
        CHECK(rb_pop(&rb, &out));
        CHECK_EQ_U(out, data[i]);
    }
    CHECK(rb_pop(&rb, &out));
    CHECK_EQ_U(out, 0x66u);
    CHECK(rb_pop(&rb, &out));
    CHECK_EQ_U(out, 0x77u);
}

static void test_push_many(void)
{
    ring_buffer_t rb;
    rb_init(&rb);

    uint8_t data[RB_CAPACITY] = {0x11, 0x22, 0x33, 0x44, 0x55};
    size_t stored = rb_push_many(&rb, data, sizeof(data));
    CHECK_EQ_U(stored, RB_CAPACITY);
    CHECK_EQ_U(rb_count(&rb), RB_CAPACITY);

    uint8_t out;
    for (size_t i = 0; i < RB_CAPACITY; i++) {
        CHECK(rb_pop(&rb, &out));
        CHECK_EQ_U(out, data[i]);
    }
}

static void test_empty_pop_untouched(void)
{
    ring_buffer_t rb;
    rb_init(&rb);

    uint8_t out = 0xFF;
    CHECK(!rb_pop(&rb, &out));
    CHECK_EQ_U(out, 0xFFu);
}

int main(void)
{
    test_init();
    test_push_pop();
    test_full_buffer();
    test_wrap_around();
    test_push_many();
    test_empty_pop_untouched();
    return OGE_REPORT();
}

